export const mid: Line[] = [
  ['Un script clásico con async…', ['espera al parseo completo y respeta el orden entre scripts', 'se ejecuta en cuanto descarga, sin orden garantizado frente a otros async', 'no se descarga hasta el primer clic', 'solo corre si además es un módulo'], 'b', 'async baja en paralelo y corre al llegar, aunque el parser no haya terminado. Varios async no se ordenan entre sí.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/script'],
  ['En un script type="module", ¿qué cambia async?', ['Lo vuelve un script clásico', 'Le quita el CORS', 'Lo ejecuta antes de descargarse', 'Lo corre en cuanto está listo, en vez de esperar como defer'], 'd', 'Sin async, el módulo espera a que el documento esté parseado. Con async se ejecuta al descargar.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/script'],
  ['Un script type="module" de otro origen…', ['no se ejecuta si esa respuesta no autoriza CORS', 'corre igual que un script clásico sin cabeceras', 'solo falla cuando lleva defer', 'manda cookies aunque el servidor responda con un asterisco'], 'a', 'Los módulos se piden con CORS. Si el otro origen no permite leer la respuesta, el módulo no corre.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/script'],
  ['disabled="false" en un botón…', ['lo deja activo, porque el valor es la palabra false', 'solo afecta al color', 'lo desactiva: en un booleano basta con que el atributo esté', 'es inválido y el navegador lo ignora'], 'c', 'La cadena false no apaga el atributo. Si disabled está presente, el botón queda desactivado.', 'https://developer.mozilla.org/en-US/docs/Glossary/Boolean/HTML'],
  ['Un checkbox desmarcado, al enviar…', ['viaja con el value vacío', 'no se incluye en el envío', 'viaja como false', 'bloquea el formulario'], 'b', 'Solo la casilla marcada es un control con éxito. La desmarcada no aporta name ni valor.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/input/checkbox'],
  ['Un checkbox marcado y sin value envía…', ['una cadena vacía', 'true', 'el texto del label', 'on'], 'd', 'Sin value, el navegador manda on. Si escribes value="si", el marcado envía si.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/input/checkbox'],
  ['Un option sin atributo value envía…', ['el texto del option', 'el índice, empezando en cero', 'null', 'el id del select'], 'a', 'Si omites value, el valor es el texto. Si lo pones, se envía el atributo y no la etiqueta visible.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/option'],
  ['Un input de texto sin name…', ['se envía con la clave input', 'se envía vacío', 'no entra en el envío', 'anula el formulario'], 'c', 'Sin name no hay campo con éxito. Se puede rellenar y el formulario no incluye ese dato.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/input'],
  ['Dos inputs de texto con el mismo name, ambos rellenos…', ['solo viaja el segundo', 'los dos se envían, con la clave repetida', 'el navegador los une con una coma', 'no viaja ninguno'], 'b', 'Cada control con éxito aporta su pareja. La misma clave puede aparecer más de una vez.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/input'],
  ['Hay dos botones submit con name. ¿Cuál añade su value al envío?', ['Los dos', 'Ninguno: el value de un botón no se envía', 'Siempre el primero del documento', 'Solo el que se pulsa'], 'd', 'El botón que dispara el envío es el único submit con éxito. El otro no mete su name ni su value.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/button'],
  ['Al enviar, input type="image"…', ['incluye las coordenadas del clic', 'se comporta como un checkbox', 'no puede ser el control de envío', 'manda el alt como valor'], 'a', 'Es un botón de envío gráfico. El navegador añade la x y la y del clic.', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Elements/input/image'],
  ['formaction en un botón submit…', ['cambia el method a get', 'salta la validación', 'usa esa URL para ese envío, en lugar del action del form', 'solo vale si el botón está fuera del form'], 'c', 'Ese botón puede mandar los datos a otra URL. Los demás siguen usando el action del form.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/button'],
  ['formnovalidate en un botón submit…', ['quita required del HTML', 'omite la validación nativa solo en el envío de ese botón', 'impide enviar', 'equivale a disabled'], 'b', 'El resto de botones sigue validando. Sirve para un borrador que no debe frenarse por required.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/button'],
  ['Enter en un input de una línea, con un botón submit en el form…', ['inserta un salto de línea', 'no hace nada si hay más de un campo', 'cierra la pestaña', 'dispara el envío usando el primer botón submit'], 'd', 'Es el envío implícito. El navegador activa el botón submit por defecto, el primero del árbol.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/form'],
  ['Enter dentro de un textarea…', ['inserta un salto de línea y no envía el formulario', 'envía el formulario', 'borra el campo', 'equivale a pulsar reset'], 'a', 'El textarea se queda el Enter como texto. El envío queda para el botón o para un input de una línea.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/textarea'],
  ['Un fieldset con disabled…', ['desactiva solo el legend', 'no toca a los controles', 'desactiva los controles interiores, salvo los del primer legend', 'equivale a readonly en cada input'], 'c', 'El grupo queda fuera de edición y de envío. En el primer legend los controles siguen activos.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/fieldset'],
  ['readonly en un checkbox…', ['impide marcarlo y aun así lo envía', 'no aplica: la casilla sigue pudiendo cambiar', 'lo saca del envío', 'lo vacía al cargar'], 'b', 'readonly es de campos de texto y de textarea. Para fijar un checkbox se usa disabled, y entonces no se envía.', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Attributes/readonly'],
  ['El atributo pattern…', ['basta con que el texto aparezca en cualquier parte del valor', 'solo existe en type="email"', 'ignora el valor vacío y también el lleno', 'tiene que casar con el valor entero'], 'd', 'No es una búsqueda parcial. Si el patrón son tres cifras, 12x3 no vale: tiene que encajar todo el valor.', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Attributes/pattern'],
  ['Un campo con pattern, vacío y sin required…', ['cumple pattern', 'falla pattern', 'se rellena con el patrón', 'queda bloqueado y no puede enviarse nunca'], 'a', 'pattern no mira el vacío. La obligación de escribir algo es required. Vacío y opcional es válido.', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Attributes/pattern'],
  ['minlength="8" en un texto…', ['impide teclear menos de ocho caracteres', 'recorta el valor al enviar', 'frena el envío si hay texto y se queda corto', 'solo existe en textarea'], 'c', 'Se puede escribir menos. Al enviar, si hay texto y no llega al mínimo, la validación nativa lo rechaza. Vacío sin required, pasa.', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Attributes/minlength'],
  ['maxlength="20"…', ['avisa y deja seguir escribiendo', 'no deja un valor más largo: la entrada se corta en ese tope', 'cuenta palabras, no caracteres', 'solo actúa en el servidor'], 'b', 'El control no se queda con más caracteres de los dichos. El servidor sigue necesitando su propio límite.', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Attributes/maxlength'],
  ['En type="number", sin step, el valor 1.5…', ['es válido porque step solo existe si lo escribes', 'se redondea a 2 al enviar', 'se envía sin mirar el paso', 'falla la validación: el paso por defecto es 1'], 'd', 'El paso por defecto es 1. 1.5 no cae en ese paso. step="any" admite otros valores.', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Attributes/step'],
  ['Un checkbox con required…', ['tiene que estar marcado para poder enviar', 'tiene que estar desmarcado', 'exige que value sea numérico', 'solo cambia el borde'], 'a', 'required en la casilla significa marcada. No inspecciona el texto del value.', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Attributes/required'],
  ['required en uno de los radios de un grupo…', ['obliga a marcar ese radio y no otro', 'no hace nada fuera de los campos de texto', 'obliga a que algún radio del mismo name esté marcado', 'marca todos los del grupo'], 'c', 'La obligación es del grupo que comparte name. Cualquier opción de ese grupo la cumple.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/input/radio'],
  ['Un select multiple sin ninguna option seleccionada…', ['envía la primera', 'no aporta valor al envío', 'envía null', 'bloquea siempre el formulario'], 'b', 'Con multiple no se elige una opción por defecto. Si no hay selección, el campo no entra.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/select'],
  ['En un select de una sola elección, si dos option llevan selected…', ['queda la primera', 'se muestran las dos elegidas', 'el select queda vacío', 'queda la última'], 'd', 'Solo una puede estar seleccionada. Si el HTML marca varias, el navegador se queda con la última.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/option'],
  ['Si dos radios del mismo name traen checked…', ['queda marcado el último', 'quedan marcados los dos', 'no queda marcado ninguno', 'queda marcado el primero'], 'a', 'El grupo admite uno. Si el HTML trae dos checked, el navegador deja el último.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/input/radio'],
  ['Lo que lees en el value de un input file…', ['es la ruta real del disco', 'está vacío hasta el envío', 'no es la ruta real: el navegador enseña un nombre ficticio', 'se puede fijar desde script a una ruta local y el archivo se adjunta'], 'c', 'La página no ve la ruta del sistema. Por eso no se puede rellenar un file con un path del disco.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/input/file'],
  ['multiple en un input file…', ['comprime los archivos en uno', 'permite elegir varios archivos en ese control', 'los convierte en base64 visible', 'limita la subida a imágenes'], 'b', 'El mismo campo admite más de un archivo. Sin multiple, el diálogo es de un solo fichero.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/input/file'],
  ['El valor de input type="datetime-local"…', ['incluye el huso del navegador', 'va en milisegundos', 'se normaliza siempre a UTC', 'es fecha y hora locales, sin huso'], 'd', 'No guarda offset ni zona. Si el instante absoluto importa, el huso tiene que ir en otro dato.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/input/datetime-local'],
  ['Si varios elementos traen autofocus…', ['recibe el foco el primero del documento', 'se enfocan todos, uno tras otro', 'el navegador ignora autofocus', 'recibe el foco el último'], 'a', 'Solo uno se enfoca al cargar. Si hay varios, gana el primero en el árbol.', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Global_attributes/autofocus'],
  ['Pulsar el label asociado a un checkbox…', ['solo mueve el foco y no cambia la marca', 'envía el formulario', 'enfoca la casilla y cambia marcada o desmarcada', 'desactiva el campo'], 'c', 'Activar el label activa el control. En un checkbox, eso invierte checked.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/label'],
  ['Un form escrito dentro de otro form…', ['crea dos envíos anidados', 'hace que la etiqueta interior se ignore, y el cierre puede cerrar el de fuera', 'descarta el exterior', 'los convierte en un fieldset'], 'b', 'No se anidan formularios. El parser no abre el segundo, y un cierre de form cierra el que estaba abierto.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/form'],
  ['Si un div aparece mientras un p sigue abierto…', ['el div queda dentro del p', 'el navegador elimina el div', 'los dos pasan a ser span', 'el navegador cierra el p antes del div'], 'd', 'p no admite ese bloque dentro. El div empieza cuando el párrafo ya se ha cerrado.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/p'],
  ['Un atributo data-pedido="18"…', ['guarda un dato en el elemento y no se envía como campo', 'equivale a un input hidden llamado pedido', 'viaja en el formulario', 'fuerza el tipo number'], 'a', 'data-* es un dato del elemento para script o CSS. El envío solo incluye controles con name.', 'https://developer.mozilla.org/en-US/docs/Web/HTML/How_to/Use_data_attributes'],
  ['reversed en un ol…', ['da la vuelta a los li en el DOM', 'ordena el texto alfabéticamente', 'numera hacia atrás y deja los ítems en su orden', 'cambia el valor de un formulario'], 'c', 'Con tres ítems se ve 3, 2, 1. El orden del DOM, y por tanto el de lectura, no se invierte.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/ol'],
  ['Un video con sonido y autoplay…', ['arranca siempre', 'casi nunca arranca solo: hace falta un gesto, o muted', 'solo arranca en escritorio', 'arranca si tiene poster'], 'b', 'El autoplay con audio se bloquea. muted permite el arranque. El sonido entra cuando la persona lo pide.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/video'],
  ['Un video sin el atributo controls…', ['no descarga el archivo', 'se anuncia como un enlace', 'equivale a un img', 'no muestra controles nativos, y el teclado puede no tener cómo reproducirlo'], 'd', 'controls pinta play y posición. Sin ellos, hace falta una interfaz propia que también se use con teclado.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/video'],
  ['loading="lazy" en una img…', ['pide esperar a que la imagen se acerque al viewport', 'impide mostrarla', 'comprime el archivo', 'la descarga antes que el HTML'], 'a', 'Es una pista de cuándo descargar. El navegador elige la distancia. El archivo no cambia.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/img'],
  ['Varios details con el mismo name…', ['se abren siempre a la vez', 'dejan de poder abrirse', 'forman un grupo en el que abrir uno cierra otro', 'se envían como un select'], 'c', 'Ese name arma un acordeón excluyente. Sin name, cada details se abre y se cierra por su cuenta.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/details'],
  ['Un button con popovertarget="aviso"…', ['navega a #aviso', 'muestra u oculta el popover con ese id, sin escribir script', 'convierte el aviso en un modal', 'envía el formulario hacia aviso'], 'b', 'El botón queda atado a ese popover. Un clic lo abre o lo cierra.', 'https://developer.mozilla.org/en-US/docs/Web/API/Popover_API'],
  ['popover="manual"…', ['se cierra al pulsar fuera', 'deja inerte el resto de la página', 'solo puede abrirse con CSS', 'no se cierra al pulsar fuera ni al abrir otro popover'], 'd', 'El manual espera a que lo cierres. El automático se va con Escape o al pulsar fuera.', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Global_attributes/popover'],
  ['El atributo open en un dialog…', ['lo muestra y el resto de la página sigue usable', 'hace lo mismo que showModal()', 'lo convierte en un popover', 'impide cualquier cierre'], 'a', 'open enseña el diálogo sin modo modal. El modal, con el resto en pausa, es showModal().', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/dialog'],
  ['Un base href="https://cdn.ejemplo/app/"…', ['afecta solo al primer enlace', 'cambia el idioma del documento', 'resuelve los URL relativos contra esa base', 'anula los fragmentos #'], 'c', 'Un href relativo pasa a colgar de esa base. La decisión vale para el documento entero.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/base'],
  ['meta http-equiv="refresh" content="5; url=https://ejemplo.com"…', ['recarga el CSS cada cinco segundos', 'navega a esa URL cuando pasan cinco segundos', 'solo corre si JavaScript está activo', 'equivale a un enlace con target'], 'b', 'El documento programa una navegación. La persona ve el salto sin haberlo pulsado.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/meta'],
  ['size="12" en un input de texto…', ['limita el valor a 12 caracteres', 'fija la altura en 12 píxeles', 'exige como mínimo 12 caracteres', 'pide un ancho visible de unos 12 caracteres'], 'd', 'Cuántos caracteres se pueden escribir lo marca maxlength. size habla de lo que se ve.', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Attributes/size'],
  ['wrap="hard" en un textarea…', ['incluye saltos de línea en el valor enviado, según cols', 'impide pulsar Enter', 'cifra el texto', 'equivale a maxlength'], 'a', 'El valor viaja partido para que cada línea quepa en cols. Con soft, esos cortes de presentación no se envían.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/textarea'],
  ['Un select con size="4" y ninguna option selected…', ['elige la primera option', 'pasa a ser multiple', 'puede quedar sin ninguna opción elegida', 'no se llega a pintar'], 'c', 'Con size mayor que 1 se muestra una lista y no se fuerza la primera. Sin selected, puede enviarse sin valor.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/select'],
  ['autocomplete="off" en usuario o contraseña…', ['impide guardar la clave en cualquier navegador', 'es una pista, y en el login muchos navegadores la ignoran', 'cifra el campo', 'equivale a readonly'], 'b', 'off no es una orden. En credenciales el navegador puede rellenar igual. Conviene decir el dato con un token concreto.', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Attributes/autocomplete'],
  ['type="email" multiple…', ['admite un solo correo', 'envía un JSON', 'comprueba que el buzón exista', 'admite varios correos separados por comas'], 'd', 'Cada fragmento tiene que tener forma de correo. El navegador no comprueba que la cuenta exista.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/input/email'],
  ['min y max en una fecha o en un número…', ['acotan el valor, y lo que se sale no pasa la validación nativa', 'solo cambian el color del borde', 'ponen step en 1', 'impiden pegar'], 'a', 'El control puede limitar el selector. Un valor fuera de ese intervalo frena el envío nativo.', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Attributes/min'],
  ['capture="user" en un input file…', ['firma el archivo con el usuario', 'restringe la elección a PDF', 'pide capturar con la cámara o el micrófono, en vez de elegir un archivo', 'vacía el campo'], 'c', 'Es una pista para usar el dispositivo. Llega un fichero, y quien lo recibe tiene que comprobarlo.', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Attributes/capture'],
  ['enterkeyhint="send"…', ['envía el formulario al enfocar', 'cambia el rótulo de Enter en el teclado de pantalla', 'valida el campo', 'crea un botón submit'], 'b', 'Cambia la palabra de la tecla: enviar, buscar, siguiente. No añade un botón ni envía por su cuenta.', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Global_attributes/enterkeyhint'],
  ['autocapitalize="none"…', ['prohíbe las mayúsculas también con un teclado físico', 'borra el campo', 'activa el corrector', 'pide al teclado de pantalla que no ponga mayúsculas solo'], 'd', 'Encaja en un correo, un código o un usuario. Es una pista del teclado, no una regla de validación.', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Global_attributes/autocapitalize'],
  ['spellcheck="false"…', ['pide no subrayar la ortografía en ese elemento', 'corrige el texto al enviar', 'bloquea el envío si hay una falta', 'traduce el campo'], 'a', 'Es una pista para un código o un nombre propio. No revisa nada fuera del navegador.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Global_attributes/spellcheck'],
  ['Si el documento no trae doctype, el navegador…', ['se niega a abrirlo', 'usa siempre el modo estándar', 'puede entrar en quirks y aplicar reglas viejas de la caja', 'ignora todo el CSS'], 'c', 'El doctype pide el modo estándar. En quirks, el cálculo de anchos y márgenes no es el que el CSS actual describe.', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Quirks_Mode_and_Standards_Mode'],
  ['draggable="true"…', ['al soltar, mueve el nodo a otro padre', 'permite arrastrar el elemento; qué dato se suelta lo decide un script', 'lo convierte en un select', 'lo saca del tabulador'], 'b', 'El atributo autoriza el arrastre. El destino y los datos viajan en los eventos de drag and drop.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Global_attributes/draggable'],
  ['Un link de CSS con media="print"…', ['no se descarga', 'sustituye a todas las hojas de pantalla', 'solo se aplica en el móvil', 'aplica esa hoja al imprimir, no a la pantalla'], 'd', 'media elige el contexto. La hoja que lees en pantalla puede no ser la de la impresora.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/link'],
  ['headers="precio" en un td…', ['liga la celda al th cuyo id es precio', 'fija el ancho de la columna', 'ordena la columna al pulsar', 'une tres columnas'], 'a', 'La celda declara sus encabezados por id. Sirve cuando scope no describe ese cruce.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/td'],
  ['Si el hash de integrity no coincide con el archivo…', ['el script se ejecuta y queda un aviso', 'el script se ejecuta solo en localhost', 'ese script no se usa', 'el archivo se trata como texto visible'], 'c', 'La comprobación falla cerrada. La misma URL con otro contenido no llega a ejecutarse.', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Attributes/integrity'],
  ['srcdoc en un iframe…', ['inyecta una hoja de estilos', 'usa ese HTML como documento del marco', 'aplica sandbox por defecto', 'bloquea los scripts de la página padre'], 'b', 'El documento va escrito en el atributo. Donde srcdoc se entiende, ese HTML es el que se muestra.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/iframe'],
  ['default en un track de subtítulos…', ['traduce el audio', 'oculta la pista', 'cambia el lang de la página', 'pide usar esa pista si la persona no ha elegido otra'], 'd', 'Sugiere la pista inicial. Una preferencia ya guardada de la persona puede imponerse.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/track'],
  ['preload="none" en un video…', ['pide no bajar el medio hasta que haya que reproducirlo', 'impide pulsar play', 'descarga el archivo entero al parsear', 'equivale a autoplay'], 'a', 'Es una pista para no gastar datos. metadata pide lo justo para duración y tamaño. auto puede adelantar mucho más.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/video'],
  ['crossorigin="anonymous" en un script…', ['adjunta las cookies de ese origen', 'ejecuta el archivo saltándose CORS', 'pide el recurso en modo CORS y sin credenciales', 'calcula integrity por su cuenta'], 'c', 'La petición no lleva cookies. Hace falta para leer una respuesta de otro origen o para poder comprobar su hash.', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Attributes/crossorigin'],
  ['Una option con disabled…', ['se elige y luego no se envía', 'la persona no puede elegirla', 'se envía siempre como cadena vacía', 'cierra el select'], 'b', 'Se puede mostrar, y no se puede escoger. No es un valor que la persona deje marcado a propósito.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/option'],
  ['Cuando la validación nativa impide enviar…', ['el foco se queda donde estaba', 'se cierra la pestaña', 'se vacían los campos inválidos', 'el foco va al primer control inválido y se muestra su mensaje'], 'd', 'El navegador enfoca el primer fallo y enseña el aviso nativo. Con novalidate, ese gesto no ocurre.', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Guides/Constraint_validation'],
  ['Un select required cuya option elegida tiene value=""…', ['no cumple required', 'required lo da por relleno', 'pasa a ser multiple', 'salta solo a la siguiente option'], 'a', 'El valor vacío cuenta como campo sin elegir. Una primera option Elige… con value="" obliga a cambiarla.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/select'],
  ['Si pattern no se cumple y el input tiene title…', ['title pasa a ser el label', 'el formulario se envía igual', 'el aviso nativo puede incluir ese title', 'title se envía como si fuera el value'], 'c', 'El bocadillo del navegador no queda asociado al campo como un error de la página. title no lo sustituye.', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Attributes/pattern'],
  ['Un script clásico con nomodule…', ['lo ejecutan también los navegadores con módulos', 'lo ignoran los navegadores que saben ejecutar módulos', 'se convierte en type="module"', 'se descarga y no se ejecuta nunca'], 'b', 'nomodule es el respaldo clásico. Quien entiende módulos no lo corre además del module.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/script'],
  ['Un script clásico en el body, sin async ni defer…', ['se descarga al final de la página, siempre', 'equivale a defer', 'se salta si el body ya empezó', 'para el parseo, se ejecuta y luego el parser sigue'], 'd', 'El HTML se detiene en ese script. Uno largo puesto pronto retrasa el resto del documento.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/script'],
]

export const senior: Line[] = [
  ['¿Qué hace tabindex="-1"?', ['Se puede enfocar por script y no entra en el tabulador', 'Lo convierte en botón', 'Lo coloca el primero de la tabulación', 'Lo quita del lector de pantalla'], 'a', 'El -1 saca el elemento del recorrido Tab y lo deja listo para un focus() al abrir un panel.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Global_attributes/tabindex'],
  ['En un grupo de radios hechos a mano, el tabulador…', ['para en cada radio', 'usa un tabindex positivo en el elegido', 'entra una vez: las flechas cambian la opción y Tab sale del grupo', 'no entra, porque todos llevan tabindex="-1" incluido el activo'], 'c', 'El grupo es un solo tab stop. Las flechas mueven la opción. El activo lleva tabindex="0" y el resto -1.', 'https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Reference/Roles/radio_role'],
  ['Un botón que muestra u oculta un panel propio…', ['con aria-haspopup ya queda abierto', 'tiene que reflejar el estado en aria-expanded', 'usa aria-pressed', 'esconde el panel con aria-hidden y lo deja enfocable'], 'b', 'aria-expanded dice si el panel está abierto. El atributo no lo abre: el script, o un details, cambia el estado.', 'https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Reference/Attributes/aria-expanded'],
  ['Un botón que se queda activado, como la negrita de un editor, se anuncia con…', ['aria-checked', 'aria-selected', 'aria-current', 'aria-pressed'], 'd', 'aria-pressed es el estado de un botón conmutador. aria-checked es de checkbox o switch. aria-selected, de una opción en un conjunto.', 'https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Reference/Attributes/aria-pressed'],
  ['El enlace de la sección actual, dentro de la navegación, lleva…', ['aria-current="page"', 'aria-selected="true"', 'aria-pressed="true"', 'disabled'], 'a', 'aria-current="page" marca la página o la vista en curso. No desactiva el enlace ni lo convierte en pestaña.', 'https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Reference/Attributes/aria-current'],
  ['aria-selected encaja en…', ['un checkbox', 'un interruptor de ajustes', 'la opción activa de un listbox o de unas pestañas', 'el enlace de la página actual'], 'c', 'selected dice cuál está elegida dentro de un conjunto. El marcado de un checkbox es aria-checked. La página actual es aria-current.', 'https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Reference/Attributes/aria-selected'],
  ['role="switch"…', ['es un enlace con dos href', 'es un control de encendido: aria-checked y Espacio para cambiarlo', 'sustituye a un grupo de radios', 'no necesita estado'], 'b', 'El switch se comporta como un checkbox con otro significado. El rol no pulsa solo: hace falta teclado y aria-checked.', 'https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Reference/Roles/switch_role'],
  ['Si el título del cuadro ya está escrito en la página, el nombre accesible se saca con…', ['un aria-label de otra frase', 'title', 'placeholder', 'aria-labelledby apuntando a ese título'], 'd', 'labelledby usa el texto visible, así lo que se oye y lo que se lee no se separan cuando el título cambia.', 'https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Reference/Attributes/aria-labelledby'],
  ['aria-errormessage…', ['apunta al error del control cuando el estado es inválido', 'borra el texto del error', 'sustituye a required', 'mueve el foco él solo'], 'a', 'Se combina con aria-invalid. El mensaje sigue teniendo que existir en la página: el atributo solo lo señala.', 'https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Reference/Attributes/aria-errormessage'],
  ['Un "Guardado" que no debe cortar lo que se está leyendo encaja con…', ['role="alert"', 'aria-modal="true"', 'role="status"', 'role="application"'], 'c', 'status es una región que espera. alert interrumpe. Un guardado rutinario no es una alerta.', 'https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Reference/Roles/status_role'],
  ['Dos elementos nav en la misma página…', ['necesitan nombres accesibles distintos', 'están prohibidos por el HTML', 'el segundo se ignora en el árbol', 'comparten el nombre Navegación y con eso basta'], 'a', 'Cada landmark de navegación se distingue, por ejemplo con aria-labelledby a su título. Si no, se oyen dos iguales.', 'https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Reference/Roles/navigation_role'],
  ['Un header dentro de un article…', ['es el banner de la página', 'pasa a ser un h1', 'no es el banner: ese papel es del header de alto nivel', 'se anuncia como contentinfo'], 'c', 'El header de una pieza es el encabezado de esa pieza. El banner es el de la página, no uno anidado en el article.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/header'],
  ['El footer de un article…', ['es el contentinfo de toda la página', 'es el pie de esa pieza, no el contentinfo del documento', 'sustituye a address', 'se anuncia como banner'], 'b', 'contentinfo es el pie del documento. El footer interior cierra el article y no ocupa ese landmark.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/footer'],
  ['role="presentation" en un ul…', ['mantiene la lista y solo quita los puntos', 'lo convierte en nav', 'le añade un nombre accesible', 'le quita la semántica de lista'], 'd', 'presentation (o none) hace que esa lista no se anuncie como lista. No es la herramienta para quitar el estilo.', 'https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Reference/Roles/presentation_role'],
  ['Un botón que solo enseña un icono…', ['necesita un nombre accesible, con aria-label o con texto que no estorbe a la vista', 'se anuncia con el nombre del archivo', 'no necesita nombre si el dibujo es claro', 'queda resuelto con title en el móvil'], 'a', 'Sin nombre, el control es un botón vacío. El icono no se lee como etiqueta. title no cubre el táctil.', 'https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Reference/Attributes/aria-label'],
  ['En un enlace que ya tiene texto, la imagen de dentro…', ['repite ese texto en el alt', 'se deja sin alt y el enlace pierde el nombre', 'lleva alt vacío, para no duplicar el nombre', 'sustituye al href'], 'c', 'El nombre del enlace junta el texto y el alt. Si dicen lo mismo, se oye dos veces. Con el texto, el alt vacío sobra menos.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/img'],
  ['Dejar en title la única explicación de un icono…', ['basta en táctil y en el lector', 'no es un nombre fiable: en muchos táctiles title no llega a mostrarse', 'equivale a aria-label', 'sustituye al alt de un img'], 'b', 'title es un complemento, no el canal principal. Lo que hay que entender tiene que estar en un nombre o en texto visible.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Global_attributes/title'],
  ['Si una sigla tiene que entenderse, ¿dónde va la forma larga?', ['Basta con title en el abbr', 'En aria-hidden, para no repetir', 'En kbd', 'Escrita en el texto la primera vez que aparece'], 'd', 'title del abbr sale al pasar el puntero. Quien no usa puntero puede no oír la expansión. El texto no depende de eso.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/abbr'],
  ['¿Cuándo encaja autofocus al cargar la página?', ['Cuando esa vista empieza en ese campo, como un buscador o un código', 'En un artículo, para saltar al primer anuncio', 'En todos los formularios, por defecto', 'En el pie, además de otro autofocus arriba'], 'a', 'El foco se va a ese control y se pierde el principio de la página. Tiene sentido si la tarea nace ahí.', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Global_attributes/autofocus'],
  ['Si quitas el outline del foco…', ['el elemento deja de poder enfocarse', 'focus-visible desaparece del navegador', 'hace falta otro indicador visible cuando se llega con teclado', 'tabindex vuelve a pintar el anillo'], 'c', 'El anillo se puede cambiar de forma. Sin ningún indicador, quien usa teclado no ve dónde está.', 'https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/Properties/outline'],
  ['pointer-events: none en un botón visible…', ['lo saca del tabulador y del envío', 'el puntero lo atraviesa, y el teclado todavía puede enfocarlo y activarlo', 'equivale a disabled', 'lo quita del árbol de accesibilidad'], 'b', 'Quitar el puntero no desactiva el control. Para que no se use, disabled, o un control que de verdad no reciba la acción.', 'https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/Properties/pointer-events'],
  ['¿Cuándo eliges popover="manual"?', ['Cuando debe cerrarse al pulsar fuera', 'Cuando el resto de la página tiene que quedar inerte', 'Cuando confirmas un borrado', 'Cuando dentro hay datos a medias y un cierre al pulsar fuera los tiraría'], 'd', 'El automático se va solo. Si la persona está a mitad de algo, el manual espera un cierre explícito.', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Global_attributes/popover'],
  ['aria-haspopup="menu"…', ['anuncia que hay un menú y no lo abre ni mueve el foco', 'crea el menú y lo rellena', 'equivale a un select', 'encierra el tabulador en el botón'], 'a', 'El atributo avisa. Abrir, cerrar con Escape y mover las opciones sigue siendo comportamiento que tienes que construir.', 'https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Reference/Attributes/aria-haspopup'],
  ['Los enlaces de la navegación del sitio…', ['van en role="menu" para que sean más accesibles', 'van en role="application"', 'siguen en nav como enlaces: menu es para acciones', 'van en role="listbox"'], 'c', 'menu se recorre con flechas y lanza acciones. Una barra de destinos se recorre con Tab y sigue siendo navegación.', 'https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Reference/Roles/menu_role'],
  ['role="application" en el body…', ['mejora cualquier página para el lector', 'hace que el lector suelte sus atajos de lectura: no es un rol de página entera', 'equivale a main', 'arregla el orden del tabulador'], 'b', 'application se reserva a un widget que de verdad se come el teclado. En el documento, estorba la lectura.', 'https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Reference/Roles/application_role'],
  ['Un input con una lista propia, para ser un combobox, …', ['basta un div absoluto y un click', 'usa role="menu" en la lista', 'usa role="dialog" en la lista', 'lleva aria-expanded, aria-controls y el teclado de un listbox'], 'd', 'El rol no abre la lista ni mueve la opción. Si ese teclado no va a existir, un select ya lo trae.', 'https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Reference/Roles/combobox_role'],
  ['aria-activedescendant sirve para…', ['dejar el foco en el contenedor y señalar la opción activa', 'meter cada opción en el tabulador', 'sustituir a aria-selected', 'cerrar el popup al pulsar Escape por su cuenta'], 'a', 'El DOM sigue enfocado en el widget. El atributo dice qué opción tiene el foco virtual, y esa opción no necesita tabindex.', 'https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Reference/Attributes/aria-activedescendant'],
  ['headers, y no solo scope, hace falta cuando…', ['quieres fijar el ancho de la columna', 'la tabla tiene una fila de th y ya está', 'una celda depende de varios encabezados y scope no puede señalarlos todos', 'la tabla se va a ordenar con script'], 'c', 'scope cubre una fila o una columna. En un cruce más raro, la celda lista los id de sus th.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/td'],
  ['allow-scripts y allow-same-origin en un iframe cuyo HTML no controlas…', ['es la combinación más segura', 'dejan que ese documento anule el sandbox', 'equivalen a no poner sandbox, solo en el CSS', 'solo afectan a las imágenes'], 'b', 'Con scripts y el mismo origen, el marco puede alcanzar tu página y quitarse el aislamiento. Si no es tuyo, no juntes los dos.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/iframe'],
  ['rel="opener" junto a target="_blank"…', ['anula window.opener', 'equivale a noreferrer', 'impide abrir la pestaña', 'devuelve window.opener, el acceso que noopener había cortado'], 'd', 'opener deshace el corte. La página nueva puede volver a manejar la tuya. No lo añadas por inercia.', 'https://developer.mozilla.org/en-US/docs/Web/API/Window/opener'],
  ['rel="noreferrer" en un enlace saliente…', ['no manda Referer y también deja window.opener en null', 'solo cambia el color del enlace', 'fuerza la descarga', 'mantiene opener y añade el Referer'], 'a', 'Sirve cuando la URL de origen no debe viajar, por ejemplo si lleva un token. El destino no recibe esa cabecera.', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Attributes/rel/noreferrer'],
  ['integrity en un script de otro origen…', ['basta el hash, sin crossorigin', 'hace la descarga más rápida', 'pide crossorigin y, si el hash no cuadra, el script no se ejecuta', 'firma las cookies de sesión'], 'c', 'El navegador comprueba el archivo antes de ejecutarlo. Sin CORS, un origen distinto no queda anclado por el hash.', 'https://developer.mozilla.org/en-US/docs/Web/Security/Subresource_Integrity'],
  ['Un href que empieza por javascript:…', ['es un botón bien construido', 'ejecuta código en tu página y no es una navegación', 'queda aislado como un iframe', 'equivale a type="button"'], 'b', 'El enlace promete un destino y aquí corre script. La acción va en un button. El destino, en un href real.', 'https://developer.mozilla.org/en-US/docs/Web/URI/Reference/Schemes/javascript'],
  ['Meter un base href desde HTML que no controlas…', ['cambia un solo enlace', 'desactiva los formularios', 'arregla los relativos rotos y nada más', 'recoloca los URL relativos del documento: enlaces, imágenes y envíos'], 'd', 'base es de toda la página. Un base inyectado puede sacar el formulario de tu origen.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/base'],
  ['dir="auto" en el comentario que escribió un usuario…', ['elige la dirección de ese bloque según su texto', 'lo fuerza siempre de izquierda a derecha', 'traduce el comentario', 'aísla una sola palabra en medio de tu frase'], 'a', 'auto deduce la dirección base de ese elemento. Una palabra ajena dentro de una frase tuya se aísla con bdi.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Global_attributes/dir'],
  ['Una cita en francés dentro de una página en español…', ['hereda el idioma y no hace falta marcarla', 'se resuelve con translate="yes"', 'lleva lang="fr" en la cita', 'se marca con dir="rtl"'], 'c', 'lang en ese tramo cambia la pronunciación. Si no está, el lector usa la voz del idioma de la página.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Global_attributes/lang'],
  ['translate="no" en una marca o en un identificador…', ['impide que el lector lo pronuncie', 'pide que la traducción deje ese tramo tal cual', 'cifra el texto', 'equivale a lang'], 'b', 'Sirve para un nombre de producto o un código que una traducción automática estropearía. No esconde el texto.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Global_attributes/translate'],
  ['hidden="until-found"…', ['es un disclosure con botón', 'deja el bloque visible y solo lo oculta al lector', 'equivale a disabled', 'oculta el bloque y la búsqueda de la página puede revelarlo'], 'd', 'Quien no usa buscar no llega. No sustituye a un control que abra el contenido.', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Global_attributes/hidden'],
  ['loading="lazy" en la imagen del mayor pintado inicial…', ['retrasa el recurso que tenía que llegar antes', 'es lo correcto para mejorar ese pintado', 'comprime el archivo', 'equivale a fetchpriority="high"'], 'a', 'lazy es para lo que está fuera del primer pantallazo. La imagen que abre la vista se pide pronto.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/img'],
  ['fetchpriority="high"…', ['se pone en todas las imágenes para ir más rápido', 'fija el orden de pintado píxel a píxel', 'adelanta un recurso, y pierde sentido si todo va en high', 'sustituye a loading="lazy"'], 'c', 'Es una pista de red. Si todo es prioritario, no hay nada que adelantar.', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Attributes/fetchpriority'],
  ['preconnect hacia un origen…', ['descarga ya esa web entera', 'abre la conexión antes, y solo compensa si ese origen se usa enseguida', 'equivale a precargar la hoja de estilos', 'guarda la respuesta para la próxima visita'], 'b', 'Cada conexión compite al arrancar. Un origen que quizá uses después no se preconecta por si acaso.', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Attributes/rel/preconnect'],
  ['preload="auto" en un vídeo que mucha gente no reproduce…', ['es la opción que menos datos gasta', 'impide pulsar play', 'equivale a none', 'puede bajar un archivo grande sin que nadie le dé a reproducir'], 'd', 'auto deja adelantar mucho. Si el vídeo no es la razón de entrar, none o metadata esperan al gesto.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/video'],
  ['Al crear una clave nueva, el autocomplete que orienta al gestor es…', ['new-password', 'current-password', 'off, que los navegadores siempre respetan', 'username'], 'a', 'new-password pide generar una clave. current-password rellena la ya guardada, que es la del inicio de sesión.', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Attributes/autocomplete'],
  ['Con novalidate, si compruebas los campos en script…', ['el navegador sigue llevando el foco al primer error', 'required desaparece del DOM', 'el foco tiene que ir al resumen o al primer campo inválido', 'basta un borde rojo'], 'c', 'novalidate apaga el foco y el aviso nativos. Un error solo pintado no lo oye quien va por teclado.', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Guides/Constraint_validation'],
  ['Un header fijo tapa el control que acaba de recibir el foco. ¿Qué reserva ese hueco?', ['Un tabindex positivo en el header', 'scroll-padding en el documento', 'aria-hidden en el header', 'autofocus en el header'], 'b', 'Al mover el foco o saltar a un ancla, el padding de scroll deja el destino por debajo de la barra.', 'https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/Properties/scroll-padding'],
  ['¿Cuántos main visibles admite una página?', ['Uno por cada section', 'Ninguno: main ya no se usa', 'Dos si hay buscador y contenido', 'Uno. Otro main solo puede estar hidden'], 'd', 'main es el contenido único de la vista. Dos a la vez duplican el landmark. El que no toca se oculta.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/main'],
  ['El nombre accesible de un dialog que ya tiene encabezado visible sale de…', ['aria-labelledby hacia ese encabezado', 'un aria-label con un texto más corto y distinto', 'el title del documento', 'el primer botón del diálogo'], 'a', 'Lo que se oye es el título que se ve. Un aria-label paralelo se desfasa en cuanto el encabezado cambia.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/dialog'],
  ['Confirmar que se borra algo…', ['cabe en un popover que se cierra al pulsar fuera', 'cabe en un details', 'va en un dialog modal, con un botón que dice qué se borra', 'puede ser un enlace'], 'c', 'El modal pide una decisión. Cerrar al pulsar el fondo es propio de un popover, y ahí se confirma sin mirar.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/dialog'],
  ['Un control inutilizable cuyo motivo quieres que se oiga al llegar a él…', ['lleva disabled, que ya explica el motivo', 'lleva aria-disabled, y el script bloquea la acción: ARIA no la bloquea', 'lleva readonly', 'lleva hidden'], 'b', 'disabled lo saca del tabulador y del envío, así que nadie llega al motivo. aria-disabled deja el foco, y el click lo anulas tú.', 'https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Reference/Attributes/aria-disabled'],
  ['En un radiogroup propio, Tab…', ['recorre cada opción', 'no puede entrar', 'envía el formulario', 'entra una vez, las flechas cambian la opción y el siguiente Tab sale'], 'd', 'El grupo es un solo paso de tabulador. Cada ítem es radio y el contenedor es radiogroup.', 'https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Reference/Roles/radiogroup_role'],
  ['El estado indeterminado de un checkbox…', ['se pone con la propiedad indeterminate y no es un tercer valor del envío', 'se escribe con el atributo indeterminate', 'se envía como mixed', 'equivale a required'], 'a', 'Lo que viaja sigue siendo marcado o no. El tercer estado es visual. En un control propio se anuncia con aria-checked="mixed".', 'https://developer.mozilla.org/en-US/docs/Web/API/HTMLInputElement/indeterminate'],
  ['Apoyar la interfaz en accesskey…', ['es la vía recomendada para los atajos', 'sustituye al tabulador', 'choca con atajos del lector y del navegador', 'equivale a tabindex="0"'], 'c', 'La tecla elegida puede estar ocupada. accesskey puede ser un añadido, no el único camino hasta la acción.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Global_attributes/accesskey'],
  ['Dos campos con el mismo id…', ['el for del label nombra a los dos', 'el for, el fragmento y la búsqueda por id caen en el primero', 'el navegador renombra el segundo', 'un aria-label en el padre lo corrige'], 'b', 'El segundo se queda sin identificador útil. Se duplica menos: se cambian los id. ARIA no repara el fragmento ni el label.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Global_attributes/id'],
  ['Un svg en línea que informa, y no decora…', ['se entiende al leer cada path', 'usa alt, como un img', 'con envolverlo en figure ya tiene nombre', 'necesita un nombre, title o aria-label, y role="img" si no quieres recorrer su interior'], 'd', 'Si el dibujo es decorativo, aria-hidden="true" evita deletrear los trazos. Un svg metido en img lleva el alt en el img.', 'https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Reference/Roles/img_role'],
  ['aria-atomic="true" en una región que se actualiza…', ['hace leer la región entera, no solo el nodo que cambió', 'mueve el foco al principio de la región', 'equivale a role="alert"', 'esconde los nodos que no cambiaron'], 'a', 'Hace falta cuando el trozo nuevo no se entiende solo, como un "3 resultados". Sin atomic puede oírse únicamente el 3.', 'https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Reference/Attributes/aria-atomic'],
  ['Mientras un script sustituye una lista de resultados…', ['aria-hidden en el body', 'role="alert" en cada fila nueva', 'aria-busy="true" hasta que la lista está completa, y luego se quita', 'aria-modal en la lista'], 'c', 'busy pide no anunciar el hueco a medias. Al quitarlo, se puede leer el resultado ya armado.', 'https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Reference/Attributes/aria-busy'],
  ['aria-controls…', ['mueve el foco al panel controlado', 'dice qué elemento maneja el botón, y no lo abre ni lo enfoca', 'equivale a aria-expanded', 'valida los campos de ese panel'], 'b', 'Es una referencia. Mostrar el panel, reflejar expanded y mover el foco, si toca, van aparte.', 'https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Reference/Attributes/aria-controls'],
  ['Poner una clave en un input type="hidden"…', ['la cifra en el cliente', 'la deja fuera del envío', 'la oculta en el DOM', 'solo la quita de la vista: sigue en el HTML y en el envío'], 'd', 'Quien abre el código fuente la ve. Un campo oculto no es un almacén de secretos.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/input/hidden'],
  ['aria-modal="true" en un div…', ['anuncia modalidad y no deja el resto inerte ni encierra el tabulador', 'equivale a dialog.showModal()', 'cierra el div con Escape', 'esconde el diálogo a la vista'], 'a', 'El atributo no fabrica el comportamiento. El modal nativo es dialog con showModal. Lo demás hay que programarlo.', 'https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Reference/Attributes/aria-modal'],
  ['Al abrir un dialog que borra datos, el foco inicial conviene que caiga en…', ['Borrar, para ir más deprisa', 'el body, detrás del diálogo', 'Cancelar, mediante autofocus, para que Enter no confirme', 'el enlace de saltar contenido'], 'c', 'autofocus dentro del diálogo elige el control inicial. En una acción sin vuelta atrás, ese control no es el que borra.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/dialog'],
  ['El atributo allow de un iframe…', ['acelera la descarga del marco', 'concede permisos concretos, como cámara o ubicación, y sin la directiva no se heredan', 'equivale a un sandbox vacío', 'firma el origen del padre'], 'b', 'sandbox recorta lo que el documento puede hacer. allow reparte permisos. Uno no sustituye al otro.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/iframe'],
  ['HTML de otra persona colocado en srcdoc…', ['es texto plano y no ejecuta nada', 'hereda una jaula aunque no haya sandbox', 'equivale a un textarea', 'comparte el origen de tu página salvo que sandbox le quite los scripts'], 'd', 'Sin sandbox, ese documento actúa como tuyo. Si no lo escribes tú, sandbox y sin allow-scripts.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/iframe'],
  ['Una Content-Security-Policy escrita en un meta…', ['empieza cuando el parser llega a ella y no admite frame-ancestors', 'cubre lo mismo que la cabecera HTTP', 'impide por sí sola que te incrusten en un iframe', 'se aplica antes de bajar el documento'], 'a', 'La política que tiene que valer desde el primer byte va en la cabecera. El meta no cubre las directivas que actúan antes.', 'https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/CSP'],
  ['crossorigin="use-credentials" y un servidor que responde Allow-Origin: * …', ['cargan el script con cookies', 'ignoran CORS y siguen', 'hacen que el navegador rechace el recurso', 'desactivan integrity'], 'c', 'Con credenciales, el origen permitido no puede ser el asterisco. anonymous no manda cookies. El modo y la cabecera tienen que coincidir.', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Attributes/crossorigin'],
  ['El atributo ping de un enlace…', ['es decorativo y no genera red', 'lanza un POST en segundo plano al seguir el enlace', 'equivale a noreferrer', 'firma el href'], 'b', 'Es una petición al hacer clic, no un adorno. Si mide algo, esa petición forma parte del comportamiento del enlace.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/a'],
  ['Un botón submit con formaction a otro origen…', ['solo cambia la etiqueta del botón', 'se ignora si el form ya tiene action', 'cifra el cuerpo', 'envía allí el formulario: entra en la frontera de confianza'], 'd', 'Quien inyecte ese botón elige el destino de los datos. formaction no es un detalle de presentación.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/button'],
  ['Sacar a alguien de un pago con meta refresh…', ['es un salto que no ha pedido: el redirect de verdad lo hace el servidor', 'es más seguro porque no usa JavaScript', 'cifra la URL de destino', 'equivale a cerrar un dialog'], 'a', 'refresh navega solo, aunque la persona esté leyendo. La salida de un flujo sensible va en la respuesta HTTP.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/meta'],
  ['Un iframe de un reproductor, al final de un artículo…', ['tiene que competir con el primer render, sin lazy', 'no admite loading', 'puede llevar loading="lazy" si no es lo primero que la vista tiene que pintar', 'se arregla solo con sandbox'], 'c', 'lazy aparta ese marco de la descarga inicial. Si el vídeo es el motivo de la página, no se deja para luego.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/iframe'],
  ['decoding="async" en la imagen que abre la vista…', ['es siempre lo más rápido para el primer pintado', 'puede retrasarlo: en esa imagen deja elegir al navegador', 'equivale a loading="lazy"', 'reduce el peso del archivo'], 'b', 'async decodifica fuera del camino crítico. En una imagen secundaria ayuda. En la principal, auto suele ser más honesto.', 'https://developer.mozilla.org/es/docs/Web/HTML/Reference/Elements/img'],
  ['role="presentation" en un control que la persona puede pulsar…', ['solo le quita el borde', 'le añade el teclado que le faltaba', 'le quita el rol y no le regala el comportamiento de un control', 'equivale a aria-pressed'], 'c', 'presentation es para lo que no debe anunciarse como control. En un botón, borra el significado y el teclado no aparece por ello.', 'https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Reference/Roles/presentation_role'],
]
